// 7.3.10 telemetry helpers. Both are failure-tolerant: they never throw and
// never block the capture-timeout log. Missing data is reported as null so the
// payload can still distinguish "unknown" from a real zero.
function readInterceptStats(xfilter) {
  const fallback = {
    reqXHR: null,
    reqFetch: null,
    reqBeacon: null,
    reqOther: null,
    totalRequestsSeen: null,
    anyGraphQLSeen: null,
    graphqlSeen: null,
    graphqlRejected: null,
    pageStatsSeen: null,
  };

  try {
    if (! xfilter || typeof xfilter.getInterceptStats !== 'function') return fallback;

    return Object.assign(fallback, xfilter.getInterceptStats() || {});
  } catch (_error) {
    return fallback;
  }
}

function readBoilerplateCache() {
  // ff_boilerplate_at is stored in unix SECONDS (getUnixTime), so cacheAgeSec is
  // computed in seconds. cachePresent: true = a cached boilerplate exists,
  // false = none present, null = the read failed/timed out (unknown).
  return new Promise(resolve => {
    let settled = false;
    const done = value => {
      if (settled) return;
      settled = true;
      resolve(value);
    };

    setTimeout(() => done({ cachePresent: null, cacheAgeSec: null }), 2000);

    try {
      chrome.storage.local.get([ 'ff_boilerplate_at' ], result => {
        if (chrome.runtime.lastError || ! result || ! result.ff_boilerplate_at) {
          return done({ cachePresent: false, cacheAgeSec: null });
        }

        done({
          cachePresent: true,
          cacheAgeSec: Math.floor(Date.now() / 1000) - result.ff_boilerplate_at,
        });
      });
    } catch (_error) {
      done({ cachePresent: null, cacheAgeSec: null });
    }
  });
}

