function facebookComposerFill(postText) {
  function waitForElement(selector, parent, timeoutMs) {
    return new Promise((resolve, reject) => {
      var existing = parent.querySelector(selector);

      if (existing) return resolve(existing);

      var timer = setTimeout(() => {
        observer.disconnect();
        reject(new Error('Timeout waiting for ' + selector));
      }, timeoutMs);

      var observer = new MutationObserver(() => {
        var el = parent.querySelector(selector);

        if (el) {
          clearTimeout(timer);
          observer.disconnect();
          resolve(el);
        }
      });

      observer.observe(parent, { childList: true, subtree: true });
    });
  }

  return (async () => {
    try {
      // Find the "What's on your mind?" trigger
      var trigger = null;
      var buttons = document.querySelectorAll('div[role="button"]');

      for (var i = 0; i < buttons.length; i++) {
        var text = (buttons[i].textContent || '').toLowerCase();

        if (text.indexOf('what\'s on your mind') !== -1) {
          trigger = buttons[i];
          break;
        }
      }

      if (! trigger) {
        var spans = document.querySelectorAll('span');

        for (var j = 0; j < spans.length; j++) {
          var spanText = (spans[j].textContent || '').toLowerCase();

          if (spanText.indexOf('what\'s on your mind') !== -1) {
            trigger = spans[j].closest('div[role="button"]') || spans[j];
            break;
          }
        }
      }

      if (! trigger) {
        return { success: false, error: 'Could not find composer trigger' };
      }

      trigger.click();

      // Wait for composer dialog
      var dialog = await waitForElement('div[role="dialog"]', document.body, 5000);

      // Find contenteditable inside dialog
      var editor = dialog.querySelector('div[contenteditable="true"][role="textbox"]')
        || dialog.querySelector('div[contenteditable="true"]');

      if (! editor) {
        return { success: false, error: 'Could not find composer editor' };
      }

      editor.focus();

      // Insert text using execCommand
      var inserted = document.execCommand('insertText', false, postText);

      // Verify insertion; fallback to textContent assignment
      if (! inserted || ! editor.textContent.includes(postText)) {
        editor.textContent = postText;
        editor.dispatchEvent(new Event('input', { bubbles: true }));
      }

      return { success: true };
    } catch (e) {
      return { success: false, error: e.message || 'Unknown error' };
    }
  })();
}








