// CONCATENATED MODULE: ./xfilter-robot/friendfilter/playbook/friendfilter_jobs.js
function getEventName(jobName, stage) {
  switch (jobName) {
  case 'fetch_user_friends': return `scan_friends_${stage}`;
  case 'initial_user_setup': return `fetch_user_profile_${stage}`;
  case 'fetch_user_engagements': return `scan_engagements_${stage}`;
  case 'remove_user_friends': return `remove_friends_${stage}`;
  case 'add_user_friends': return `add_friends_${stage}`;
  case 'fetch_user_friends_friendship_date': return `fetch_friendship_date_${stage}`;
  case 'fetch_user_newsfeed': return `fetch_user_newsfeed_${stage}`;
  }
}

async function friendfilter_jobs_before() {
  const eventName = getEventName(this.name, 'start');

  this.xfilter.backendNotifyExtension(eventName);
}

async function friendfilter_jobs_after() {
  const eventName = getEventName(this.name, 'done');

  if (this.name == 'fetch_user_engagements') {
    this.xfilter.notifyAppTabs('disable_sync_engagement');
  }
  await this.xfilter.backendNotifyExtension(eventName);

  if (this.fetchedCount > 0 || this.fetchedPostsCount > 0 || this.removedFriendsCount > 0 || this.fetchedFriendShipDateCount > 0) {
    this.setPercentsDone(100);
  }
}

async function failure() {
  const eventName = getEventName(this.name, 'error');

  this.xfilter.backendNotifyExtension(eventName);
}

async function friendfilter_jobs_final() {
  if (this.tab) this.tab.close();
  this.xfilter.notifyAppTabs('reload_friends');
}

async function runCommonTasks() {
  await this.runTask('hydrate_facebook_scripts');
  await this.runTask('facebook_inner_html');
  await this.runTask('detect_error_page');
  await this.runTask('ensure_facebook_authenticated');
  await this.runTask('check_user_username_exists');
  await this.runTask('ensure_user_username_not_changed');
  await this.runTask('intercept_facebook_request');
}

