// Error names that are GLOBAL/fatal to the whole removal batch, not specific
// to one friend. When the per-friend unfriend attempt throws one of these we
// re-throw so the JOB-level handlers in
// xfilter/background/job/error_handlers.js can act on the whole job (session
// refresh, stop, rate-limit postpone, transport retry). Skipping individual
// friends cannot fix any of these, so grinding through the batch would be
// pointless and noisy.
const GLOBAL_FATAL_ERROR_NAMES = [
  'FacebookNotAuthorized',
  'FacebookUsernameIncorrect',
  'FacebookProfessionalModeDetected',
  'FacebookGraphQLRateLimitError',
  'FacebookGraphQLSoftRateLimitError',
  'FacebookGraphQLTransientError',
  'FacebookErrorPage',
  'CooldownRequired',
  'PortDisconnected',
];

// A failure is GLOBAL/fatal when its name is in the list above, OR when it is a
// FacebookGraphQLError that signals a session/auth problem. The session/auth
// detection mirrors handlerFacebookGraphQLError in
// xfilter/background/job/error_handlers.js so the per-friend loop and the
// job-level handler agree on what a session error is. Everything else --
// notably a plain FacebookGraphQLError such as "Sorry, something went wrong" or
// "Query Error" -- is treated as PER-FRIEND and is skip-and-continue.
function isGlobalFatalError(exception) {
  if (! exception || ! exception.name) return false;
  if (GLOBAL_FATAL_ERROR_NAMES.includes(exception.name)) return true;

  if (exception.name === 'FacebookGraphQLError') {
    const fbCode = exception.data && exception.data.code;
    const isAuthCode = [ 10, 102, 190 ].includes(fbCode) || (fbCode >= 200 && fbCode <= 299);
    const messageText = `${exception.message || ''} ${(exception.data && exception.data.summary) || ''}`;
    const isSessionMessage = /session.?expir|not authorized|login|auth|permission|token/i.test(messageText);

    return Boolean(isAuthCode || isSessionMessage);
  }

  return false;
}

